#include <iostream>
#include <string>
using namespace std;

int main() {
    int age = 10;
    int day = 6;

    // A chain, because these are ranges.
    string category;
    int price = 0;
    if (age < 5) {
        category = "Infant";
        price = 0;
    } else if (age < 13) {
        category = "Child";
        price = 120;
    } else {
        category = "Adult";
        price = 250;
    }

    // A switch, because these are fixed values.
    string dayName;
    switch (day) {
        case 1: dayName = "Monday"; break;
        case 2: dayName = "Tuesday"; break;
        case 3: dayName = "Wednesday"; break;
        case 4: dayName = "Thursday"; break;
        case 5: dayName = "Friday"; break;
        case 6: dayName = "Saturday"; break;
        case 7: dayName = "Sunday"; break;
        default: dayName = "Unknown";
    }

    // A nested if: the surcharge is only for paying tickets.
    bool weekend = day == 6 || day == 7;
    if (price > 0) {
        if (weekend) {
            price += 50;
        }
    }

    // A ternary, because it only chooses some words.
    string rate = weekend ? "weekend rate" : "weekday rate";

    cout << dayName << ", " << rate << endl;
    cout << category << ": " << price << endl;
    return 0;
}

